INSERT INTO scholarship (name, provider, description, amount, application_url, min_age, max_age, required_gender, eligible_region, required_military_status, max_income_bracket, min_gpa, min_gpa_basis, requires_disability, foreigner_eligibility, grade_level, major, affiliated_institution, min_credits, admission_score_condition, headcount, application_period, eligible_university, eligible_college, required_enrollment_status, min_grade, max_grade, required_degree_level, category_l1, category_l2) VALUES
('특별장학금(신입생)', '대전대학교', '한의예과·군사학과 제외. 공통기준: 수능 영어영역 2등급 이내, 탐구영역(직업탐구 제외) 2과목 평균 반영. 일반학과(부)는 국어·수학·탐구영역 중 2개 영역 백분위 합 160점 이상, 간호학과·물리치료학과는 국어·수학·탐구영역 백분위 합 240점 이상. 등록금 전액, 이후 매학기 직전학기 15학점 이상 취득·평점평균 3.5 이상 유지 시 4년간 지급(수시/정시 공통).', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, '수능 영어 2등급 이내, 국어·수학·탐구 백분위 합 160점(일반학과)/240점(간호·물리치료학과) 이상', NULL, '입학 시 전형 결과로 자동 선발 (수시/정시 모집요강 참고)', '대전대학교', NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_internal', 'academic_merit'),
('군사학과여학생특별장학금', '대전대학교', '군사학과 여자 신입생 대상. 수능 국어·수학·영어 평균 2등급 이내는 등록금 전액(이후 직전학기 15학점+평점평균 4.0 이상 유지 시 4년), 평균 3등급 이내는 수업료 일부(직전학기 15학점+평점평균 3.5 이상 유지)(수시/정시 공통).', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, 'female', NULL, NULL, NULL, 3.5, 'semester', NULL, NULL, NULL, '군사학과', NULL, NULL, '수능 국어·수학·영어 평균 2등급 이내(전액) 또는 3등급 이내(일부)', NULL, '입학 시 전형 결과로 자동 선발 (수시/정시 모집요강 참고)', '대전대학교', NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_internal', 'academic_merit'),
('신입생 전형별 수석·차석 장학금', '대전대학교', '교과면접전형·교과중점전형·지역인재Ⅰ·Ⅱ전형(통합선발)·혜화인재전형·고른기회전형·농어촌학생전형·특성화고교졸업자전형·기회균형전형·군사학과전형 등 각 전형별로 모집단위(학과) 또는 단과대학별 수석·차석을 선발해 수업료 일부 지급(한의예과는 인문/자연 통합 1명). 실기위주전형(커뮤니케이션디자인학과·영상애니메이션학과·공연예술콘텐츠학과·생활체육학과·건강운동관리학과)도 모집단위별 수석을 별도 선발. 이후 직전학기 15학점 이상 취득·평점평균 3.5 이상 유지 시 1년간 지급. 전형 종류가 매칭 가능한 필드로 표현되지 않아 하나로 통합 기재함.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '입학 시 전형 결과로 자동 선발 (수시/정시 모집요강 참고)', '대전대학교', NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_internal', 'academic_merit'),
('체육특기자장학금(신입생)', '대전대학교', '검도·펜싱·정구·복싱 특기자 대상(수시). 등록금 전액, 1년 지급.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '입학 시 전형 결과로 자동 선발 (수시 모집요강 참고)', '대전대학교', NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_internal', 'activity_merit'),
('전체수석장학금(정시)', '대전대학교', '정시 전체수석 합격자 대상. 등록금 전액, 이후 직전학기 15학점 이상 취득·평점평균 3.5 이상 유지 시 졸업 시까지 지급.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '입학 시 전형 결과로 자동 선발 (정시 모집요강 참고)', '대전대학교', NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_internal', 'academic_merit'),
('단대수석장학금(정시)', '대전대학교', '정시 단과대학별 수석 합격자 대상. 등록금 전액, 이후 직전학기 15학점 이상 취득·평점평균 3.5 이상 유지 시 일반학과 3년/한의예과 4년간 지급.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '입학 시 전형 결과로 자동 선발 (정시 모집요강 참고)', '대전대학교', NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_internal', 'academic_merit');
INSERT INTO scholarship (name, provider, description, amount, application_url, min_age, max_age, required_gender, eligible_region, required_military_status, max_income_bracket, min_gpa, min_gpa_basis, requires_disability, foreigner_eligibility, grade_level, major, affiliated_institution, min_credits, admission_score_condition, headcount, application_period, eligible_university, eligible_college, required_enrollment_status, min_grade, max_grade, required_degree_level, category_l1, category_l2) VALUES
('성적우수장학금(대전대)', '대전대학교', '학과·학년별 재학인원 대비 성적순으로 5단계 차등 지급: 최우수성적(등록금100%), 성적우수A(70%), 성적우수B(50%), 성적우수C(30%), 성적우수D(15%). 공통 최소기준은 직전학기 15학점 이상 취득(최종학년 10학점)·평점평균 3.0 이상(F·N·미이수 과목 있으면 제외). 매학기 지급.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 3.0, 'semester', NULL, NULL, NULL, NULL, NULL, '직전학기 15학점 이상(최종학년 10학점)', NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('복지장학금(대전대)', '대전대학교', '국가장학금 1~8분위 대상자 중 직전학기 12학점 이상 취득·백분위점수 80점 이상인 자. 소득분위별 차등 지급, 매학기.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, 8, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '직전학기 12학점 이상', NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'welfare_living'),
('마중물장학금', '대전대학교', '국가장학금 0분위(기초생활수급자) 대상자 중 직전학기 12학점 이상 취득·백분위점수 80점 이상인 자. 등록금의 20%, 매학기.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '직전학기 12학점 이상', NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'welfare_living'),
('장학사정관장학금', '대전대학교', '장학사정관 심사로 차등 지급(등록금 일부, 매학기). 대상: 다자녀(3자녀 이상), 중증질병 및 상해(1년 이상 연속 의료비 정산서), 실직가정·재난 및 재해(주민센터 확인서), 긴급가계곤란자(부도·파산 관계서류), 희망장학금(부모 중 장애등급 1~3급), 다문화가정자녀(부모 중 한 사람이 외국인, 귀화자·결혼이민자 포함), 기타 경제적 어려움 소명자 — 여러 특수상황 조건이 하나의 장학금에 OR로 묶여있어 구조화된 필드 하나로 표현 불가(matching_gaps.md 9번·12번 참고).', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
('희망도전장학금', '대전대학교', '당해학기 국가장학금 신청자 중 성적기준 미달로 수혜받지 못한 자(직전학기 백분위점수 80점 미만). 등록금 일부, 매학기.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'welfare_living'),
('교직원자녀장학금(대전대)', '대전대학교', '전임교원·정규직원의 직계자녀 대상. 직전학기 15학점 이상 취득(최종학년 10학점)·평점평균 3.0 이상(유급제도 시행학과는 2.5 이상) 필요. 등록금의 50%, 매학기.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 3.0, 'semester', NULL, NULL, NULL, NULL, NULL, '직전학기 15학점 이상(최종학년 10학점)', NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
('재단직원자녀장학금', '대전대학교', '법인 임직원, 부속병원 및 혜화병원 정규직원, 학교설립유공자의 직계자녀 대상. 등록금의 50%, 매학기.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
('열정장학금', '대전대학교', '장애지원센터에 등록된 장애학생 대상(직전학기 실점평균 70점 이상). 중증장애 100만원 / 경증장애 30만원, 매학기.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
('동문자녀장학금(대전대)', '대전대학교', '본교 재학생 중 부모 1인이 본교 졸업생인 경우. 학기당 30만원.', 300000, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
('보훈장학금(대전대)', '대전대학교', '보훈청의 대학수업료 등 면제대상증명서를 발급받은 국가유공자 본인 및 그 자녀 대상(본인은 성적 제한 없음, 자녀는 직전학기 백분위점수 70점 이상). 등록금 전액, 매학기. 국가보훈처/한국장학재단을 통한 교외 나라사랑장학금과는 별개의 대전대학교 자체 교내 장학금.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
('새터민장학금(대전대)', '대전대학교', '국내 고등학교 졸업 또는 고졸 이상 학력 인정일로부터 5년 이내에 입학·편입학한 북한이탈주민 본인 및 그 자녀 대상(본인은 2회 연속 70점 미만이면 제한, 자녀는 직전학기 백분위점수 70점 이상). 등록금 전액, 매학기.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
('고시장학금(대전대)', '대전대학교', '국가고시(5급 이상) 및 이에 준하는 고시 1차·2차·최종 합격자 대상(직전학기 15학점 이상 취득(최종학년 10학점)·평점평균 3.0 이상). 1차합격자 등록금의 50%, 2차합격자·최종합격자는 등록금 전액. 수시 지급.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 3.0, 'semester', NULL, NULL, NULL, NULL, NULL, '직전학기 15학점 이상(최종학년 10학점)', NULL, NULL, '수시 (합격 발표 후 신청, 대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('가족장학금(대전대)', '대전대학교', '직계가족 2인 이상이 본교 재학 중인 경우, 직전학기 성적 백분위점수 70점 이상인 재학생 각자에게 학기당 50만원 지급.', 500000, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
