('마일리지장학금(대전대)', '대전대학교', '6개 영역(학업/봉사/취업 등)에 마일리지를 부여해 누적점수가 500점 이상일 경우 장학금으로 전환(직전학기 15학점 이상 신청, 평점평균 2.0 이상). 등록금 일부, 한 학기 지급.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 2.0, 'semester', NULL, NULL, NULL, NULL, NULL, '직전학기 15학점 이상', NULL, NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('기타 역량강화·마일리지 장학금(대전대)', '대전대학교', '역량강화 관련 6개 세부 항목에 등록금 일부를 지급(대부분 수시/매학기): 아너스장학금(프로그램 참가 적극성 및 교육성과 우수자, 평가 후 차등지급), 공모전및경시대회(교내 각종 공모전·경시대회 우수자), 도서관마일리지(도서포인트70%+좌석이용포인트30% 누적자), 독서인증(도서관 추천도서 읽고 시험 패스한 자), 학생역량강화장학금(비전탐색·비전설계·DUIMS·블로그기자단·ASEAN포럼·스포츠건강체력·학생홍보단·현장실습 등 프로그램 참여자, 한학기), 기금인출장학(발전기금·장학기금으로 적립된 장학금, 해당부서 요청에 의해 지급).', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '수시/매학기 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('융합인재장학금(대전대)', '대전대학교', '융·복합 전공교육과정 이수학생 대상. 해당학기 평점평균 3.5 이상, 동일학기 융복합전공 교과목(제1전공 포함) 6학점 이상 이수자 중 성적순 선발. 6학점 이상 10만원 / 9학점 이상 20만원(총 70명 이내), 매학기.', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, 'semester', NULL, NULL, NULL, NULL, NULL, '동일학기 융복합전공 교과목 6학점 이상', '총 70명 이내', NULL, '매 학기 초 공지 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('디딤돌장학금(대전대)', '대전대학교', '비교과 프로그램 참가에 포인트를 부여해 누적 포인트가 있는 자를 선발. 등록금 일부, 연 1회 지급. 학교 자체 비교과 이수 조건이라 별도 매칭 필드 없이 텍스트로만 기록(matching_gaps.md 11번 방침).', NULL, 'https://www.dju.ac.kr/dju/cm/cntnts/cntntsView.do?mi=1172&cntntsId=1064', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '연 1회 (대전대학교 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'activity_merit');
INSERT INTO scholarship (name, provider, description, amount, application_url, min_age, max_age, required_gender, eligible_region, required_military_status, max_income_bracket, min_gpa, min_gpa_basis, requires_disability, foreigner_eligibility, grade_level, major, affiliated_institution, min_credits, admission_score_condition, headcount, application_period, eligible_university, eligible_college, required_enrollment_status, min_grade, max_grade, required_degree_level, category_l1, category_l2) VALUES
('창업마일리지 장학금', '대전대학교 RISE사업단', '창업교과/비교과 마일리지를 취득한 재학생 대상. 창업 마일리지 신청서, 창업활동 수기, 외부 프로그램 참여 증빙자료(상장·수료증), 롤모델 창업특강 수료증 제출 필요. 매년 약 2천만원 규모를 마일리지 취득 학생들에게 지급(연례 프로그램, 2025학년도 기준 신청마감 1.19).', NULL, 'https://www.dju.ac.kr/djurise/main.do', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매년 1월경 모집 (정확한 시기는 RISE사업단 홈페이지 확인)', '대전대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'activity_merit');
INSERT INTO scholarship (name, provider, description, amount, application_url, min_age, max_age, required_gender, eligible_region, required_military_status, max_income_bracket, min_gpa, min_gpa_basis, requires_disability, foreigner_eligibility, grade_level, major, affiliated_institution, min_credits, admission_score_condition, headcount, application_period, eligible_university, eligible_college, required_enrollment_status, min_grade, max_grade, required_degree_level, category_l1, category_l2) VALUES
('대한민국 인재상', '한국장학재단(교육부)', '대한민국 국적의 만 15~34세 청년 중 탁월한 성취·창의적 사고·사회기여 등 기준에 부합하는 인재 100명 선발(대학 소속 무관, 개인 자격 신청 가능). 국무총리상 1명(상장+300만원), 교육부장관상 99명(상장+200만원). 접수 2026.7.14~8.19 18:00, 한국장학재단 누리집 신청+추천서 시도청 우편제출.', 2000000, 'https://www.dju.ac.kr/dju/na/ntt/selectNttList.do?bbsId=1853&mi=3957', 15, 34, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '100명', '2026.7.14~2026.8.19 18:00', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'national_scholarship'),
('농업인자녀장학금', '한국농어촌희망재단', '농업인 자녀 중 신청자 대상(학과·전공 제한 없음, 국가장학금 0~8분위만 신청 가능). 재학중 직전학기 백분위점수 80점 이상·취득학점 12학점 이상(농어촌희망재단 지급계획에 따라 변동 가능). 등록금 일부, 매학기.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '직전학기 12학점 이상', NULL, NULL, '매학기 (한국농어촌희망재단 공고 확인)', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'private_foundation'),
('의용소방대자녀장학금', '의용소방대', '의용소방대에서 선발된 자(의용소방대원 본인 또는 자녀) 대상. 의용소방대 자체 기준에 준해 등록금 일부 지급, 매학기.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매학기 (소속 의용소방대 확인)', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'local_gov'),
('새마을지도자자녀장학금', '새마을운동중앙회', '새마을지도자 자녀로 선발된 자 대상. 새마을회 자체 기준에 준해 등록금 일부 지급, 매학기.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매학기 (소속 새마을회 확인)', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'local_gov'),
('서울희망장학금', '(재)서울장학재단', '(재)서울장학재단의 선발 및 추천을 받은 서울 거주 대학생 대상(비서울 소재 대학 재학생 포함). 서울장학재단 자체 기준에 따라 등록금 일부 지급, 매학기.', NULL, NULL, NULL, NULL, NULL, '서울', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매학기 ((재)서울장학재단 공고 확인)', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'local_gov');
